    private JSONArray messages(JSONObject chat)throws Exception{JSONArray out=new JSONArray(),h=chat==null?null:chat.optJSONArray("history");if(h!=null)for(int i=0;i<h.length();i++){JSONObject item=h.optJSONObject(i);if(item==null)continue;String role=item.optString("role"),type=item.optString("type"),value="";if(role.equals("user")){Object c=item.opt("content");if(c instanceof String)value=(String)c;else if(c instanceof JSONArray){JSONArray parts=(JSONArray)c;for(int j=0;j<parts.length();j++){JSONObject p=parts.optJSONObject(j);if(p!=null){if(p.optString("type").equals("input_text"))value+=p.optString("text");else if(p.optString("type").equals("asterhand_attachment"))value+="\n📎 "+p.optString("name");}}}if(!value.isEmpty())out.put(new JSONObject().put("role","user").put("text",value));}
            else if(type.equals("message")||role.equals("assistant")){JSONArray parts=item.optJSONArray("content");if(parts!=null)for(int j=0;j<parts.length();j++){JSONObject part=parts.optJSONObject(j);if(part!=null)value+=part.optString("text",part.optString("refusal",""));}else value=item.optString("content","");if(!value.isEmpty())out.put(new JSONObject().put("role","assistant").put("text",value).put("label",item.optString("_asterhand_label",currentLabel())));}
            else if(type.equals("function_call"))out.put(new JSONObject().put("role","tool").put("text",AgentSession.toolLabel(item.optString("name"))));
            else if(type.equals("function_call_output")){try{JSONObject result=new JSONObject(item.optString("output","{}"));out.put(new JSONObject().put("role","tool_result").put("text",result.has("error")?result.optString("error"):result.has("exit_code")?"命令退出 "+result.optInt("exit_code"):"操作已返回").put("detail",item.optString("output")));}catch(Exception ignored){}}
        }if(out.length()==0&&chat!=null&&!chat.optString("transcript").isEmpty())out.put(new JSONObject().put("role","assistant").put("label","历史记录").put("text",chat.optString("transcript")));return out;}
    private String currentLabel(){String p=ProviderClient.id(prefs.getInt("provider",0));return prefs.getString("model."+p,"AsterHand")+" · "+AgentSession.effortLabel(prefs.getString("reasoningEffort."+p,"medium"));}
