    private final class Bridge {
        @JavascriptInterface public void dispatch(String operation,String payload,String id){
            if(id==null||!id.matches("[a-zA-Z0-9-]{1,64}"))return;
            Runnable action=()->{String result=invoke(operation,payload);main.post(()->{if(web!=null&&ready)web.evaluateJavascript("window.asterResult("+JSONObject.quote(id)+","+result.replace("\u2028","\\u2028").replace("\u2029","\\u2029")+")",null);});};if(operation.equals("restartServices"))new Thread(action,"AsterHand-recovery-request").start();else io.execute(action);
        }
        @JavascriptInterface public String invoke(String operation,String payload){try{JSONObject a=new JSONObject(payload==null?"{}":payload),result=new JSONObject();if((operation.equals("deleteProjects")||operation.equals("deleteChats"))&&AgentTaskService.snapshot(MainActivity.this).optBoolean("running"))throw new Exception("请先停止当前任务，再删除项目或对话。");switch(operation){
            case "guideComplete":if(!prefs.edit().putBoolean("userGuideCompleted.v1",true).commit())throw new Exception("无法保存引导进度，请重试。");break;
            case "qaAuthMetadata":{requireDevelopment();String stored=vault.get("oauth.credentials");JSONObject credential=stored.isEmpty()?new JSONObject():new JSONObject(stored);return new JSONObject().put("expires_at",credential.optLong("expires_at")).put("now",System.currentTimeMillis()/1000).put("hasRefresh",!credential.optString("refresh_token").isEmpty()).put("hasScope",Arrays.asList(credential.optString("scope").trim().split("\\s+")).contains("chatgpt.tokens.use.direct")).toString();}
            case "qaCore":requireDevelopment();return CoreSelfTest.runBasic(MainActivity.this).toString();
            case "qaScreenFocusMetadata":requireDevelopment();return ScreenAccessibilityService.focusMetadata().toString();
            case "qaPrivilege":requireDevelopment();return PrivilegeSelfTest.run(MainActivity.this,a.optBoolean("unavailable")?new String[]{"--bridge-unavailable"}:new String[0]).toString();
            case "qaQuestion":requireDevelopment();return CoreSelfTest.startQuestionFixture(MainActivity.this).toString();
            case "qaQuestionResult":requireDevelopment();return CoreSelfTest.questionFixtureResult(MainActivity.this).toString();
            case "qaRemotePrepare":requireDevelopment();return RemoteSelfTest.prepare(MainActivity.this,a.optString("device"),a.optString("name")).toString();
            case "qaRemoteOnce":requireDevelopment();return RemoteSelfTest.approveOnce(MainActivity.this,a.optString("id")).toString();
            case "qaRemoteOutgoing":requireDevelopment();return RemoteSelfTest.startOutgoing(MainActivity.this,a.optString("host"),a.optInt("port")).toString();
            case "qaRemotePoll":requireDevelopment();return RemoteSelfTest.pollOutgoing(MainActivity.this).toString();
            case "qaRemoteMarker":requireDevelopment();return RemoteSelfTest.outboundMarker(MainActivity.this).toString();
            case "qaRemoteCleanup":requireDevelopment();return RemoteSelfTest.cleanup(MainActivity.this).toString();
            case "state":return state().toString();
            case "servicesEnabled":ServiceMaster.set(MainActivity.this,a.optBoolean("enabled"));break;
            case "restartServices":{ServiceMaster.requireEnabled(MainActivity.this);if(!ServiceRecovery.snapshot().optBoolean("running")){java.util.concurrent.ExecutorService old=io;io=java.util.concurrent.Executors.newFixedThreadPool(4);old.shutdownNow();}return ServiceRecovery.restart(MainActivity.this).put("ok",true).toString();}
            case "minimize":main.post(()->moveTaskToBack(true));break;
            case "fullscreen":main.post(()->{if(Build.VERSION.SDK_INT>=30){if(a.optBoolean("enabled"))getWindow().getInsetsController().hide(WindowInsets.Type.systemBars());else getWindow().getInsetsController().show(WindowInsets.Type.systemBars());}});break;
            case "send":AgentSession.get(MainActivity.this).send(a.optString("text"),new JSONArray(attachments.toString()),a.optString("sourceProject"),a.optString("sourceChat"));synchronized(attachments){while(attachments.length()>0)attachments.remove(0);}break;
            case "stop":AgentSession.get(MainActivity.this).stop();break;case "continue":AgentSession.get(MainActivity.this).resume();break;
            case "answer":if(!AgentTaskService.answer(a.optString("text"),a.optJSONArray("selections"),a.optString("taskId"),a.optString("questionId")))throw new Exception("请使用当前问题的选项回答；问题可能已更新，权限批准需明确点选。");break;
            case "createProject":projects.createProject(a.optString("name"));break;case "createChat":projects.createChat();break;
            case "selectProject":projects.selectProject(a.optString("id"));clearAttachments();break;case "selectChat":projects.selectChat(a.optString("id"));clearAttachments();break;
            case "renameProject":if(!projects.renameProject(a.optString("id"),a.optString("name")))throw new Exception(projects.lastError());break;
            case "renameChat":if(!projects.renameChat(a.optString("id"),a.optString("name")))throw new Exception(projects.lastError());break;
            case "deleteProjects":result=projects.deleteProjects(strings(a.optJSONArray("ids")),a.optBoolean("files"));break;
            case "deleteChats":result.put("deleted",projects.deleteChats(strings(a.optJSONArray("ids"))));break;
            case "saveSettings":saveHapticSettings(a);saveSettings(a);break;
            case "models":{String p=ProviderClient.id(a.optInt("provider",prefs.getInt("provider",0)));String token=p.equals("chatgpt")?ChatGPTAuth.accessToken(vault):vault.get(ProviderClient.apiKeyName(p));result.put("models",ProviderClient.models(p,token,prefs.getString("base."+p,"")));break;}
            case "permissionProbe":result=new PrivilegeManager(MainActivity.this).probe(PrivilegeManager.Mode.parse(a.optString("mode")));break;
            case "permissionSelect":AgentTaskService.stop();new PrivilegeManager(MainActivity.this).select(PrivilegeManager.Mode.parse(a.optString("mode")));break;
            case "accessibility":main.post(()->ScreenAccess.openSettings(MainActivity.this));break;
            case "overlayPermission":main.post(()->startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName()))));break;
            case "overlay":main.post(()->{if(a.optBoolean("enabled"))FloatingOverlayService.show(MainActivity.this);else FloatingOverlayService.hide(MainActivity.this);});break;
            case "attach":main.post(()->pickFile(a.optBoolean("images")));break;case "removeAttachment":synchronized(attachments){int i=a.optInt("index",-1);if(i>=0&&i<attachments.length())attachments.remove(i);}break;
            case "login":main.post(()->ChatGPTAuth.signIn(MainActivity.this,vault,a.optBoolean("another"),(account,error)->main.post(()->{if(error!=null)toast(error.getMessage());emit();})));break;
            case "cancelLogin":ChatGPTAuth.cancelSignIn();break;case "signOut":ChatGPTAuth.signOut(vault);break;
            case "voice":ServiceMaster.requireEnabled(MainActivity.this);main.post(()->voiceToggle());break;
            case "voiceSubmit":VoiceController.get(MainActivity.this).submitUtterance();break;
            case "voiceInterrupt":VoiceController.get(MainActivity.this).interruptSpeech();break;
            case "voiceSettings":{VoiceController v=VoiceController.get(MainActivity.this);if(a.has("language"))v.setLanguage(a.optString("language","system"));if(a.has("silenceSeconds"))v.setSilenceSeconds((float)a.optDouble("silenceSeconds",1.5));if(a.has("idleTimeoutSeconds"))v.setIdleTimeoutSeconds(a.optInt("idleTimeoutSeconds",5));break;}
            case "voiceShortcut":main.post(()->{if(!VoiceShortcuts.requestPin(MainActivity.this))toast("当前桌面不支持添加快捷方式，可长按应用图标进入语音。");});break;
            case "micMute":VoiceController.get(MainActivity.this).setMicMuted(a.optBoolean("value"));break;case "speechMute":VoiceController.get(MainActivity.this).setSpeechMuted(a.optBoolean("value"));break;
            case "notifications":main.post(()->notificationPermission());break;
            case "hideKeyboard":main.post(()->{web.clearFocus();((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(web.getWindowToken(),0);});break;
            case "terminal":ServiceMaster.requireEnabled(MainActivity.this);result=new PrivilegeManager(MainActivity.this).terminal(a.optString("action"),a,"local-ui",new PrivilegeManager(MainActivity.this).getMode());break;
            case "remote":if(!a.optString("action").isEmpty())ServiceMaster.requireEnabled(MainActivity.this);result=remote(a);break;
            case "effects":{android.content.SharedPreferences.Editor editor=getSharedPreferences("effects",0).edit();for(String k:new String[]{"task","ai_control","remote_control","remote_connected"})if(a.has(k))editor.putBoolean(k,a.optBoolean(k));if(a.has("edge_width"))editor.putFloat("edge_width",(float)Math.max(2,Math.min(24,a.optDouble("edge_width",10))));if(a.has("edge_opacity"))editor.putFloat("edge_opacity",(float)Math.max(.1,Math.min(1,a.optDouble("edge_opacity",.7))));editor.apply();break;}
            case "export":main.post(()->startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/zip").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"AsterHand-projects.zip"),3102));break;
            case "openProjectHomepage":
            case "openGitHubProfile":{
                String url="openGitHubProfile".equals(operation)?AppInfo.GITHUB_PROFILE_URL:AppInfo.REPOSITORY_URL;
                main.post(()->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){toast(e.getMessage());}});
                break;
            }
            case "uninstall":main.post(()->startActivity(new Intent(Intent.ACTION_DELETE,Uri.parse("package:"+getPackageName()))));break;
            case "haptic":Haptics.play(MainActivity.this,web,a.optString("reason","tap"));break;
            default:throw new Exception("未知操作。");}
            emit();return result.put("ok",true).toString();
        }catch(Exception e){try{return new JSONObject().put("error",e.getMessage()==null?e.getClass().getSimpleName():e.getMessage()).toString();}catch(Exception ignored){return "{\"error\":\"操作失败\"}";}}}
    }
    JSONObject handleAppRPC(JSONObject a)throws Exception{
        String action=a.optString("action"),id=a.optString("id");
        if(action.equals("capabilities"))return new JSONObject().put("version",1).put("ui_required",true).put("groups",new JSONArray(Arrays.asList("project","chat","ai","attachment","settings","voice","services")));
        if(action.equals("ai.status"))return AgentTaskService.snapshot(this);
        if(action.equals("project.list")||action.equals("chat.list")){JSONObject s=state();return new JSONObject().put("projects",s.getJSONArray("projects")).put("project",s.optString("currentProject")).put("chat",s.optString("currentChat"));}
        if(action.equals("chat.read")){JSONObject chat=projects.currentChat();if(chat==null||!id.equals(chat.optString("id")))throw new Exception("请先选择目标对话");return new JSONObject().put("chat",chat);}
        if(action.equals("project.export"))return new JSONObject().put("project",projects.currentProject()).put("includes_credentials",false);
        if(action.startsWith("project.")||action.startsWith("chat.")){
            if(AgentTaskService.snapshot(this).optBoolean("running"))throw new Exception("请先停止当前任务");boolean ok=false;
            switch(action){case "project.create":ok=projects.createProject(a.optString("name"))!=null;break;case "chat.create":ok=projects.createChat()!=null;break;case "project.select":ok=projects.selectProject(id);break;case "chat.select":ok=projects.selectChat(id);break;case "project.rename":ok=projects.renameProject(id,a.optString("name"));break;case "chat.rename":ok=projects.renameChat(id,a.optString("name"));break;case "project.delete":if(!a.optBoolean("confirm"))throw new Exception("删除需要 confirm:true");ok=projects.deleteProjects(Collections.singleton(id),false).optInt("deleted")>0;break;case "chat.delete":if(!a.optBoolean("confirm"))throw new Exception("删除需要 confirm:true");ok=projects.deleteChats(Collections.singleton(id))>0;break;default:throw new Exception("未知项目操作");}
            if(!ok)throw new Exception("项目操作失败");emit();return new JSONObject().put("ok",true).put("project",projects.currentProject().optString("id")).put("chat",projects.currentChat().optString("id"));
        }
        if(action.equals("ai.send")){JSONObject task=AgentTaskService.snapshot(this);if(task.optBoolean("running")&&!a.optString("job").equals(task.optString("id")))throw new Exception("追加消息需要当前任务标识");AgentSession.get(this).send(a.optString("text"),new JSONArray(attachments.toString()),a.optString("project"),a.optString("chat"));clearAttachments();return AgentTaskService.snapshot(this);}
        if(action.startsWith("ai.")){JSONObject task=AgentTaskService.snapshot(this);if(!a.optString("job").equals(task.optString("id")))throw new Exception("任务标识已变化");switch(action){case "ai.stop":AgentSession.get(this).stop();break;case "ai.continue":AgentSession.get(this).resume();break;case "ai.answer":if(!AgentTaskService.answer(a.optString("text"),a.optJSONArray("selections"),a.optString("job"),a.optString("question")))throw new Exception("回答不符合当前问题");break;default:throw new Exception("此任务操作不支持");}return new JSONObject().put("accepted",true);}
        if(action.equals("attachment.list"))return new JSONObject().put("attachments",new JSONArray(attachments.toString()));
        if(action.equals("attachment.cancel")){JSONObject upload=rpcUploads.remove(id);if(upload!=null)new File(upload.getString("path")).delete();return new JSONObject().put("ok",true);}
        if(action.equals("attachment.chunk")){
            JSONObject p=projects.currentProject(),chat=projects.currentChat();if(AgentTaskService.snapshot(this).optBoolean("running")||!a.optString("project").equals(p.optString("id"))||!a.optString("chat").equals(chat.optString("id")))throw new Exception("项目或任务已变化");
            if(!id.matches("[a-f0-9-]{36}"))throw new Exception("传输标识无效");String name=a.optString("name");int total=a.optInt("total"),offset=a.optInt("offset");byte[] bytes=android.util.Base64.decode(a.getString("data"),android.util.Base64.DEFAULT);
            if(name.isEmpty()||name.equals(".")||name.equals("..")||name.matches(".*[\\p{Cntrl}].*")||!new File(name).getName().equals(name)||name.length()>120||name.contains("\\")||total<1||total>8*1024*1024||offset<0||offset>total||bytes.length<1||bytes.length>192*1024||bytes.length>total-offset||attachments.length()>=4)throw new Exception("附件分块无效");
            JSONObject upload=rpcUploads.get(id);if(upload==null){if(offset!=0||rpcUploads.size()>=4)throw new Exception("传输不存在或过多");File path=File.createTempFile("asterhand-upload-",".part",getCacheDir());upload=new JSONObject().put("path",path.getAbsolutePath()).put("offset",0).put("total",total).put("name",name).put("chat",chat.optString("id"));rpcUploads.put(id,upload);}
            if(upload.getInt("offset")!=offset||upload.getInt("total")!=total||!upload.getString("name").equals(name)||!upload.optString("chat").equals(chat.optString("id")))throw new Exception("附件分块顺序不一致");File path=new File(upload.getString("path"));try(OutputStream out=new FileOutputStream(path,true)){out.write(bytes);}upload.put("offset",offset+bytes.length);
            if(offset+bytes.length==total){File folder=new File(p.optString("workspace"),"Attachments");folder.mkdirs();File target=new File(folder,UUID.randomUUID()+"-"+name);try(InputStream in=new FileInputStream(path);OutputStream out=new FileOutputStream(target)){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);}finally{path.delete();rpcUploads.remove(id);}String mime=java.net.URLConnection.guessContentTypeFromName(name);JSONObject file=new JSONObject().put("path",target.getAbsolutePath()).put("name",name).put("mime",mime==null?"application/octet-stream":mime).put("bytes",total);attachments.put(file);emit();return new JSONObject().put("complete",true).put("attachment",file);}
            return new JSONObject().put("complete",false).put("offset",offset+bytes.length);
        }
        if(action.equals("attachment.clear")){clearAttachments();return new JSONObject().put("ok",true);}
        if(action.equals("attachment.add")){if(AgentTaskService.snapshot(this).optBoolean("running"))throw new Exception("请等待任务结束");File source=new File(a.optString("path"));if(!source.isAbsolute()||!source.isFile()||source.length()>8*1024*1024||attachments.length()>=4)throw new Exception("附件路径无效或超过上限");File folder=new File(projects.currentProject().optString("workspace"),"Attachments");folder.mkdirs();String name=source.getName();File target=new File(folder,UUID.randomUUID()+"-"+name);long count=0;try(InputStream in=new FileInputStream(source);OutputStream out=new FileOutputStream(target)){byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1){count+=n;if(count>8*1024*1024)throw new Exception("附件超过上限");out.write(bytes,0,n);}}catch(Exception e){target.delete();throw e;}String mime=java.net.URLConnection.guessContentTypeFromName(name);JSONObject file=new JSONObject().put("path",target.getAbsolutePath()).put("name",name).put("bytes",count).put("mime",mime==null?"application/octet-stream":mime);attachments.put(file);emit();return new JSONObject().put("attachment",file);}
        if(action.equals("ui.open")){switch(a.optString("page")){case "settings":case "projects":case "voice":case "remote":case "effects":String page=a.optString("page");if(page.equals("voice"))voiceStart();else if(web!=null)web.evaluateJavascript("nav("+JSONObject.quote(page)+")",null);return new JSONObject().put("opened",page);default:throw new Exception("页面无效");}}
        Set<String> keys=new HashSet<>(Arrays.asList("uiLanguage","background","appearance","capsuleLocked","hapticStyle","model","base","reasoningEffort","provider","overlay"));
        if(action.equals("settings.get")){JSONObject s=state().getJSONObject("settings"),out=new JSONObject();for(String key:keys)if(s.has(key))out.put(key,s.get(key));String provider=ProviderClient.id(prefs.getInt("provider",0));for(String key:Arrays.asList("model","base","reasoningEffort"))out.put(key,prefs.getString(key+"."+provider,""));out.put("provider",prefs.getInt("provider",0)).put("overlay",FloatingOverlayService.enabled(this));return new JSONObject().put("settings",out);}
        if(action.equals("settings.set")){if(AgentTaskService.snapshot(this).optBoolean("running"))throw new Exception("请等待任务结束");JSONObject values=a.getJSONObject("values");Iterator<String> names=values.keys();while(names.hasNext()){String key=names.next();if(!keys.contains(key))throw new Exception("此设置需在手机上修改或不支持");Object value=values.get(key);if(Arrays.asList("background","capsuleLocked","overlay").contains(key)){if(!(value instanceof Boolean))throw new Exception("开关需要布尔值");}else if(key.equals("provider")){if(!(value instanceof Number)||(values.getInt(key)!=0&&values.getInt(key)!=3))throw new Exception("服务商无效");}else if(!(value instanceof String)||((String)value).length()>2048)throw new Exception("设置值无效");}
            if(values.has("appearance")&&!Arrays.asList("system","light","dark").contains(values.getString("appearance")))throw new Exception("外观无效");if(values.has("reasoningEffort")&&!Arrays.asList("","auto","none","low","medium","high","xhigh","max").contains(values.getString("reasoningEffort")))throw new Exception("推理深度无效");if(values.has("model")&&(values.getString("model").isEmpty()||values.getString("model").length()>128||values.getString("model").matches(".*\\s.*")))throw new Exception("模型 ID 无效");if(values.has("base"))ProviderClient.base("openai",values.getString("base"));if(values.optBoolean("overlay")&&!FloatingOverlayService.permitted(this))throw new Exception("请先在系统允许悬浮窗");saveHapticSettings(values);saveSettings(values);if(values.has("overlay")){if(values.getBoolean("overlay"))FloatingOverlayService.show(this);else FloatingOverlayService.hide(this);}emit();return new JSONObject().put("ok",true);}
        if(action.equals("settings.api-key")){if(AgentTaskService.snapshot(this).optBoolean("running"))throw new Exception("请等待任务结束");String key=a.getString("key");if(key.length()>8192)throw new Exception("密钥无效");if(key.isEmpty()&&!a.optBoolean("confirm"))throw new Exception("删除密钥需确认");if(key.isEmpty())vault.remove(ProviderClient.apiKeyName("openai"));else vault.put(ProviderClient.apiKeyName("openai"),key);return new JSONObject().put("saved",true);}
        if(action.equals("voice.status"))return VoiceController.get(this).snapshot();
        if(action.equals("voice.start")){ServiceMaster.requireEnabled(this);voiceStart();return new JSONObject().put("requested",true).put("system_permissions_required",true);}
        if(action.equals("voice.stop")){VoiceController.get(this).stop();return new JSONObject().put("ok",true);}
        if(action.equals("voice.mute")){VoiceController v=VoiceController.get(this);if(a.has("microphone"))v.setMicMuted(a.getBoolean("microphone"));if(a.has("speech"))v.setSpeechMuted(a.getBoolean("speech"));return v.snapshot();}
        if(action.equals("services.status")||action.equals("services.result"))return ServiceRecovery.snapshot().put("enabled",ServiceMaster.enabled(this));
        if(action.equals("services.restart")){main.postDelayed(()->ServiceRecovery.restart(this),1500);return new JSONObject().put("requested",true).put("connection_may_close",true);}
        if(action.equals("services.stop")||action.equals("services.start")){boolean enabled=action.equals("services.start");main.postDelayed(()->{try{ServiceMaster.set(this,enabled);}catch(Exception e){toast(e.getMessage());}},1500);return new JSONObject().put("requested",true).put("connection_may_close",true);}
        throw new Exception("此应用操作不支持");
    }
    private void requireDevelopment()throws Exception{if((getApplicationInfo().flags&android.content.pm.ApplicationInfo.FLAG_DEBUGGABLE)==0)throw new Exception("本地测试接口不可用。");}
    private void saveHapticSettings(JSONObject a)throws Exception{if(!a.has("hapticStyle"))return;String style=a.optString("hapticStyle");if(!Arrays.asList("system","soft","crisp","strong","firm","success","selection").contains(style))throw new Exception("未知震动样式。");prefs.edit().putString("hapticStyle",style).putBoolean("haptics",true).apply();}
    private JSONObject remote(JSONObject a)throws Exception{RemoteControlHub hub=RemoteControlHub.get(this);String action=a.optString("action");switch(action){case "discover":return new JSONObject().put("devices",hub.discover());case "begin":return hub.begin(a.optString("host"),a.optInt("port",18769));case "poll":return hub.poll(a.optString("id"));case "decide":return hub.decide(a.optString("id"),a.optString("mode"));case "trust":return hub.setTrust(a.optString("id"),a.optString("mode"));case "name":hub.setName(a.optString("name"));break;case "rename":hub.rename(a.optString("id"),a.optString("name"));break;case "pairCode":hub.setPairCode(a.optBoolean("fixed"),a.optString("code"));break;case "enabled":hub.setEnabled(a.optBoolean("enabled"));break;case "request":return hub.request(a.optString("id"),a.optString("method"),a.optJSONObject("arguments"));default:return hub.info();}return hub.info();}
    private void saveSettings(JSONObject a)throws Exception{if(a.has("uiLanguage")&&!UILocalization.valid(a.getString("uiLanguage")))throw new Exception("Invalid UI language");String p=ProviderClient.id(a.optInt("provider",prefs.getInt("provider",0)));android.content.SharedPreferences.Editor edit=prefs.edit();if(a.has("provider"))edit.putInt("provider",Math.max(0,Math.min(3,a.optInt("provider"))));for(String k:new String[]{"model","base","reasoningEffort"})if(a.has(k))edit.putString(k+"."+p,a.optString(k).trim());for(String k:new String[]{"autoAllow","aiScreen","remoteScreen","background","haptics"})if(a.has(k))edit.putBoolean(k,a.optBoolean(k));if(a.has("uiLanguage"))edit.putString("uiLanguage",a.getString("uiLanguage"));if(a.has("appearance"))edit.putString("appearance",a.optString("appearance"));if(a.has("capsuleLocked")){edit.putBoolean("capsuleLocked",a.optBoolean("capsuleLocked"));getSharedPreferences("overlay",0).edit().putBoolean("capsuleLocked",a.optBoolean("capsuleLocked")).apply();}edit.apply();if(a.has("key")){String key=a.optString("key").trim();if(!key.isEmpty())vault.put(ProviderClient.apiKeyName(p),key);}if(a.optBoolean("removeKey"))vault.remove(ProviderClient.apiKeyName(p));main.post(()->{appearance();FloatingOverlayService.refreshAppearance();AsterBackgroundService.configure(this);});}
    private void clearAttachments(){synchronized(attachments){while(attachments.length()>0)attachments.remove(0);}}
    private static List<String> strings(JSONArray array){ArrayList<String> out=new ArrayList<>();if(array!=null)for(int i=0;i<array.length();i++)out.add(array.optString(i));return out;}
    private void pickFile(boolean images){if(attachments.length()>=4){toast("每条消息最多 4 个附件。");return;}Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType(images?"image/*":"*/*").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(intent,3101);}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null)return;if(request==3101){ArrayList<Uri> uris=new ArrayList<>();if(data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount()&&i<4;i++)uris.add(data.getClipData().getItemAt(i).getUri());}else if(data.getData()!=null)uris.add(data.getData());new Thread(()->{for(Uri uri:uris)try{if(attachments.length()>=4)break;JSONObject p=projects.currentProject();File dir=new File(p.optString("workspace"),"Attachments");dir.mkdirs();String name="附件",mime=getContentResolver().getType(uri);try(android.database.Cursor c=getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}name=name.replaceAll("[\\\\/\\x00-\\x1f]","_");if(name.length()>100)name=name.substring(name.length()-100);File f=new File(dir,UUID.randomUUID()+"-"+name);int count=0;try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(f)){if(in==null)throw new IOException("无法读取选中的附件。");byte[] b=new byte[8192];int n;while(in!=null&&(n=in.read(b))!=-1){count+=n;if(count>8*1024*1024)throw new IOException("单个附件上限为 8 MiB。");out.write(b,0,n);}}catch(Exception e){f.delete();throw e;}synchronized(attachments){attachments.put(new JSONObject().put("path",f.getAbsolutePath()).put("name",name).put("mime",mime==null?"application/octet-stream":mime).put("bytes",count));}}catch(Exception e){toast(e.getMessage());}emit();},"AsterHand-Attach").start();}else if(request==3102&&data.getData()!=null){Uri uri=data.getData();new Thread(()->{try(OutputStream out=getContentResolver().openOutputStream(uri);ZipOutputStream zip=new ZipOutputStream(out)){long[] exportBytes=new long[]{0};File source=new File(getFilesDir(),"projects.json");addZip(zip,source,"projects.json",exportBytes);JSONArray ps=projects.projects();for(int i=0;i<ps.length();i++){JSONObject p=ps.getJSONObject(i);addZip(zip,new File(p.getString("workspace")),"Projects/"+p.getString("id"),exportBytes);}toast("项目与文件已导出，未包含登录密钥。");}catch(Exception e){toast("导出失败："+e.getMessage());}},"AsterHand-Export").start();}}
    private void addZip(ZipOutputStream zip,File f,String name,long[] total)throws Exception{if(!f.exists())return;if(f.isDirectory()){File[] list=f.listFiles();if(list!=null)for(File c:list){if(!c.getCanonicalPath().startsWith(f.getCanonicalPath()+File.separator))continue;addZip(zip,c,name+"/"+c.getName(),total);}}else if(f.isFile()){total[0]+=f.length();if(total[0]>128*1024*1024)throw new Exception("导出文件超过 128 MiB。");zip.putNextEntry(new ZipEntry(name));try(InputStream in=new FileInputStream(f)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)zip.write(b,0,n);}zip.closeEntry();}}
    private void voiceToggle(){if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},4101);return;}VoiceController.get(this).toggle();emit();}
    private void voiceStart(){if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},4101);return;}VoiceController.get(this).start();emit();}
    private void notificationPermission(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){if(prefs.getBoolean("notificationAsked",false)){startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName()));return;}prefs.edit().putBoolean("notificationAsked",true).apply();requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},4102);}else toast("通知已允许。");}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] result){super.onRequestPermissionsResult(request,permissions,result);if(request==4101&&result.length>0&&result[0]==PackageManager.PERMISSION_GRANTED)VoiceController.get(this).start();emit();}
    private boolean dark(){String a=prefs.getString("appearance","system");return a.equals("dark")||(a.equals("system")&&(getResources().getConfiguration().uiMode&Configuration.UI_MODE_NIGHT_MASK)==Configuration.UI_MODE_NIGHT_YES);}
    private void appearance(){boolean d=dark();int background=d?0xff111111:0xfffafafa;if(frame!=null)frame.setBackgroundColor(background);if(web!=null)web.setBackgroundColor(background);getWindow().getDecorView().setBackgroundColor(background);getWindow().setStatusBarColor(d?0xff111111:0xfffafafa);getWindow().setNavigationBarColor(d?0xff111111:0xfffafafa);getWindow().getDecorView().setSystemUiVisibility(d?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|(Build.VERSION.SDK_INT>=26?View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR:0));}
    private void toast(String value){main.post(()->Toast.makeText(this,UILocalization.t(value==null?"操作失败":value),Toast.LENGTH_LONG).show());}
    private void handleIntent(Intent intent){Uri uri=intent==null?null:intent.getData();if(uri!=null&&uri.getScheme()!=null&&uri.getScheme().equals("asterhand")&&"voice".equals(uri.getHost()))main.postDelayed(this::voiceStart,500);}
    @Override protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);handleIntent(i);emit();}
    @Override protected void onResume(){super.onResume();foreground=true;FloatingOverlayService.setAppForeground(true);AgentTaskService.addListener(this);AsterRuntime.setForeground(true);RemoteControlHub.get(this).setUiActive(true);FloatingOverlayService.restore(this);main.removeCallbacks(ticker);main.post(ticker);}
    @Override protected void onPause(){foreground=false;AsterRuntime.setForeground(false);FloatingOverlayService.setAppForeground(false);RemoteControlHub.get(this).setUiActive(false);main.removeCallbacks(ticker);AgentTaskService.removeListener(this);super.onPause();}
    @Override public void onBackPressed(){if(web!=null)web.evaluateJavascript("window.asterBack()",null);}
    @Override public void onConfigurationChanged(Configuration c){super.onConfigurationChanged(c);appearance();emit();}
    @Override protected void onDestroy(){main.removeCallbacks(ticker);AgentTaskService.removeListener(this);io.shutdownNow();if(web!=null){web.removeJavascriptInterface("AsterNative");web.destroy();web=null;}super.onDestroy();}
